function buildSegTree(nums) {
  const n=nums.length;
  const tree=new Array(4*n).fill(0);
  function build(node,l,r){
    if(l===r){tree[node]=nums[l];return;}
    const mid=Math.floor((l+r)/2);
    build(2*node,l,mid);
    build(2*node+1,mid+1,r);
    tree[node]=tree[2*node]+tree[2*node+1];
  }
  build(1,0,n-1);
  return tree;
}

