class FenwickTree {
  constructor(n){this.n=n;this.bit=new Array(n+1).fill(0);}
  lowbit(i){return i&(-i);}
  update(i,d){while(i<=this.n){this.bit[i]+=d;i+=this.lowbit(i);}}
  query(i){let s=0;while(i>0){s+=this.bit[i];i-=this.lowbit(i);}return s;}
  rangeQuery(l,r){return this.query(r)-this.query(l-1);}
}
function buildFenwick(nums){const ft=new FenwickTree(nums.length);for(let i=0;i<nums.length;i++)ft.update(i+1,nums[i]);return ft;}

