function buildSparseTable(arr){
  const n=arr.length,LOG=Math.floor(Math.log2(n))+1;
  const t=Array.from({length:n},()=>new Array(LOG).fill(0));
  for(let i=0;i<n;i++)t[i][0]=arr[i];
  for(let j=1;j<LOG;j++)
    for(let i=0;i+(1<<j)<=n;i++)
      t[i][j]=Math.min(t[i][j-1],t[i+(1<<(j-1))][j-1]);
  return t;
}

function sparseMin(table,l,r){
  const k=Math.floor(Math.log2(r-l+1));
  return Math.min(table[l][k],table[r-(1<<k)+1][k]);
}

function selectRangeDS(props){
  const{hasUpdates,updateType,queryType}=props;
  if(!hasUpdates){
    if(queryType==='min'||queryType==='max')return'Sparse Table';
    return'Prefix Sum';
  }
  if(updateType==='point'&&queryType==='prefix_sum')return'Fenwick Tree';
  if(updateType==='point')return'Segment Tree';
  return'Lazy Segment Tree';
}
